1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.controller.CityRegionResolver;
10	import org.springframework.samples.petclinic.rest.controller.EmailDomainClassifier;
11	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
12	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
13	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
14	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
15	import org.springframework.samples.petclinic.service.ClinicService;
16	import org.springframework.samples.petclinic.util.HashUtils;
17	import org.springframework.samples.petclinic.util.IdentityUtils;
18	
19	import java.time.LocalDate;
20	import java.time.Month;
21	import java.time.Period;
22	import java.util.Collection;
23	import java.util.List;
24	import java.util.Locale;
25	import java.util.OptionalInt;
26	
27	/**
28	 * Maps Owner & OwnerDto using Mapstruct
29	 */
30	@Mapper(uses = PetMapper.class)
31	public abstract class OwnerMapper {
32	
33	    /** Used to count the members of an owner's household when deriving derived fields. */
34	    @Autowired
35	    protected ClinicService clinicService;
36	
37	    /** Single source of truth for the city-to-region mapping behind an owner's locality. */
38	    @Autowired
39	    protected CityRegionResolver cityRegionResolver;
40	
41	    /** Formats the stored E.164 telephone into its human-readable display form. */
42	    @Autowired
43	    protected TelephoneNormalizer telephoneNormalizer;
44	
45	    /** Single source of truth for classifying an owner's email domain. */
46	    @Autowired
47	    protected EmailDomainClassifier emailDomainClassifier;
48	
49	    /** A city holding more than this many owners is over its soft capacity (the hard per-city
50	     *  limit, rejected on create, is 50). */
51	    private static final long CITY_SOFT_CAPACITY = 40;
52	
53	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
54	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
55	    @Mapping(target = "displayName",
56	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
57	    @Mapping(target = "initials", expression = "java(initials(owner))")
58	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
59	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
60	    @Mapping(target = "locality", expression = "java(locality(owner))")
61	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
62	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
63	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneNormalizer.toDisplayForm(owner.getTelephone()))")
64	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
65	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
66	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
67	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
68	    @Mapping(target = "riskFlag", expression = "java(riskFlag(owner))")
69	    public abstract OwnerDto toOwnerDto(Owner owner);
70	
71	    /**
72	     * The owner's risk flag: {@code true} when any of the three risk signals holds, {@code false}
73	     * otherwise. The signals are that the owner is a possible duplicate (its stored
74	     * {@code possibleDuplicate} is true), that its email domain is
75	     * {@link EmailDomainClassifier#isDisposableAdjacent disposable-adjacent}, or that its city is
76	     * {@link #cityOverSoftCapacity over its soft capacity}.
77	     */
78	    boolean riskFlag(Owner owner) {
79	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
80	            || emailDomainClassifier.isDisposableAdjacent(owner.getEmail())
81	            || cityOverSoftCapacity(owner);
82	    }
83	
84	    /**
85	     * Whether the owner's city currently holds more than its soft capacity of
86	     * {@value #CITY_SOFT_CAPACITY} owners. Cities are compared on their normalized identity, the
87	     * same key the create endpoint's per-city capacity rule uses, so the same owners are counted.
88	     */
89	    boolean cityOverSoftCapacity(Owner owner) {
90	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
91	        long ownersInCity = clinicService.findAllOwners().stream()
92	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
93	            .count();
94	        return ownersInCity > CITY_SOFT_CAPACITY;
95	    }
96	
97	    /**
98	     * The owner's self link: '/api/owners/' followed by the owner's id, or null when the
99	     * owner has no id assigned yet.
100	     */
101	    String selfLink(Owner owner) {
102	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
103	    }
104	
105	    /**
106	     * The fiscal year (starting 1 July) that {@code date} falls in, identified by the
107	     * calendar year in which the fiscal year ends: a date in July–December belongs to the
108	     * fiscal year ending the following calendar year, while January–June belongs to the one
109	     * ending that same calendar year.
110	     */
111	    public static int fiscalYear(LocalDate date) {
112	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
113	    }
114	
115	    /**
116	     * The owner's fiscal year formatted 'FY<YY>', where YY is the two-digit fiscal year of the
117	     * (business-day-adjusted) {@code registrationDate} (the fiscal year starts on 1 July) — the same
118	     * value the assigned memberId carries in its FY segment. Returns null when there is no
119	     * registrationDate. Derived from the registrationDate directly rather than by parsing it back out
120	     * of the memberId, so this user-facing field stays independent of how the memberId is composed.
121	     */
122	    String fiscalYear(Owner owner) {
123	        LocalDate registrationDate = owner.getRegistrationDate();
124	        if (registrationDate == null) {
125	            return null;
126	        }
127	        return String.format("FY%02d", fiscalYear(registrationDate) % 100);
128	    }
129	
130	    /**
131	     * The owner's age band derived from {@code birthDate} relative to the
132	     * {@code registrationDate}: 'MINOR' when under 18, 'ADULT' from 18 to 64
133	     * inclusive and 'SENIOR' at 65 or older. Returns null when either date is
134	     * absent so no band can be computed.
135	     */
136	    OwnerDto.AgeBandEnum ageBand(Owner owner) {
137	        LocalDate birthDate = owner.getBirthDate();
138	        LocalDate registrationDate = owner.getRegistrationDate();
139	        if (birthDate == null || registrationDate == null) {
140	            return null;
141	        }
142	        int age = Period.between(birthDate, registrationDate).getYears();
143	        if (age < 18) {
144	            return OwnerDto.AgeBandEnum.MINOR;
145	        }
146	        if (age < 65) {
147	            return OwnerDto.AgeBandEnum.ADULT;
148	        }
149	        return OwnerDto.AgeBandEnum.SENIOR;
150	    }
151	
152	    /**
153	     * The Luhn check digit (0-9) over the digits contained in {@code s}: from the rightmost
154	     * digit leftward, every second digit is doubled (the rightmost first) with digits over 9
155	     * reduced by 9, and the check digit makes the total a multiple of ten.
156	     *
157	     * <p>This is the single Luhn derivation behind the application's identity values; like
158	     * {@link #fiscalYear(LocalDate)} and {@link #identityKey(Owner)} it is exposed so the check
159	     * digit is computed the one way wherever an identifier is assembled, including outside this
160	     * package.
161	     */
162	    public static int luhn(String s) {
163	        int sum = 0;
164	        boolean doubling = true;
165	        for (int i = s.length() - 1; i >= 0; i--) {
166	            char c = s.charAt(i);
167	            if (c < '0' || c > '9') {
168	                continue;
169	            }
170	            int d = c - '0';
171	            if (doubling) {
172	                d *= 2;
173	                if (d > 9) {
174	                    d -= 9;
175	                }
176	            }
177	            sum += d;
178	            doubling = !doubling;
179	        }
180	        return (10 - (sum % 10)) % 10;
181	    }
182	
183	    /**
184	     * The owner's derived identity key: the SHA-256 hex digest of the normalized telephone,
185	     * the lower-cased email (or an empty string when absent) and the {@link IdentityUtils#soundex
186	     * soundex} of the last name, joined by '|'. This single key is the sole basis for duplicate
187	     * detection on create — two owners are duplicates only when their whole identityKey matches,
188	     * so two people sharing a household (a like-sounding last name and postcode) but carrying
189	     * different telephones derive different keys and are all permitted.
190	     */
191	    public static String identityKey(Owner owner) {
192	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
193	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
194	        String lastNameSoundex = IdentityUtils.soundex(owner.getLastName());
195	        return HashUtils.sha256Hex(telephone + "|" + email + "|" + lastNameSoundex);
196	    }
197	
198	    /**
199	     * The owner's preferred contact channel: 'EMAIL' when an email address is
200	     * present, otherwise 'PHONE'.
201	     */
202	    String contactPreference(Owner owner) {
203	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
204	        return hasEmail ? "EMAIL" : "PHONE";
205	    }
206	
207	    /**
208	     * The owner's locality: the plain, user-facing region derived from the owner via
209	     * {@link CityRegionResolver}, preferring the postcode over the city, or 'UNKNOWN' when neither
210	     * yields a known region. This is the region as shown to callers; it is derived straight from the
211	     * owner's city and postcode rather than read back out of an identifier, so it stays independent
212	     * of how the owner's identifiers are composed.
213	     */
214	    String locality(Owner owner) {
215	        return cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
216	    }
217	
218	    /**
219	     * The owner's segment, formatted '&lt;TIER&gt;_&lt;AREA&gt;'. TIER is 'PREMIUM' when the owner's
220	     * {@link #membershipLevel(Owner) membershipLevel} is 3 or more, otherwise 'STANDARD'. AREA is
221	     * 'METRO' when the owner's {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD),
222	     * otherwise 'REGIONAL'.
223	     */
224	    OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
225	        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
226	        boolean knownRegion = cityRegionResolver.timezoneForRegion(locality(owner)) != null;
227	        String area = knownRegion ? "METRO" : "REGIONAL";
228	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
229	    }
230	
231	    /**
232	     * The owner's IANA timezone name derived from the owner's {@link #locality(Owner) locality}
233	     * via the fixed region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
234	     * QLD -> Australia/Brisbane). Returns null when the locality is not a region in the table.
235	     */
236	    String timezone(Owner owner) {
237	        return cityRegionResolver.timezoneForRegion(locality(owner));
238	    }
239	
240	    /**
241	     * The owner's membership points: starting at 0, plus 2 when an email address is present,
242	     * plus 1 when namesakeCount is 0, plus 2 for a household of 3 or more members, plus 3 when
243	     * the owner's tenure is more than one fiscal year.
244	     */
245	    public int membershipPoints(Owner owner) {
246	        int points = 0;
247	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
248	        if (hasEmail) {
249	            points += 2;
250	        }
251	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
252	        if (uniqueName) {
253	            points += 1;
254	        }
255	        if (householdSize(owner) >= 3) {
256	            points += 2;
257	        }
258	        LocalDate registrationDate = owner.getRegistrationDate();
259	        boolean tenured = registrationDate != null
260	            && fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) > 1;
261	        if (tenured) {
262	            points += 3;
263	        }
264	        return points;
265	    }
266	
267	    /**
268	     * The owner's numeric membership level from 1 to 4, derived from {@link #membershipPoints}
269	     * via {@link #levelForPoints} and then held to the household level-ceiling by
270	     * {@link #cappedByHousehold}.
271	     */
272	    public int membershipLevel(Owner owner) {
273	        return cappedByHousehold(owner, levelForPoints(membershipPoints(owner)));
274	    }
275	
276	    /**
277	     * Hold {@code level} to the household level-ceiling: an owner's membershipLevel may not exceed
278	     * one above the current maximum membershipLevel among the household members that already
279	     * existed when this owner registered — the other, non-deleted owners sharing its householdId
280	     * that were created earlier (a strictly lower id, ids being monotonic). When no such earlier
281	     * household member exists no ceiling applies and {@code level} is returned unchanged.
282	     *
283	     * @param owner the owner whose own level is being capped
284	     * @param level the owner's uncapped membership level
285	     * @return the level, capped at one above the earlier household members' maximum
286	     */
287	    private int cappedByHousehold(Owner owner, int level) {
288	        Integer id = owner.getId();
289	        String householdId = owner.getHouseholdId();
290	        if (id == null || householdId == null) {
291	            return level;
292	        }
293	        OptionalInt maxExisting = clinicService.findAllOwners().stream()
294	            .filter(existing -> !existing.isDeleted())
295	            .filter(existing -> existing.getId() != null && existing.getId() < id)
296	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
297	            .mapToInt(this::membershipLevel)
298	            .max();
299	        return maxExisting.isEmpty() ? level : Math.min(level, maxExisting.getAsInt() + 1);
300	    }
301	
302	    /**
303	     * The numeric membership level from 1 to 4 that {@code points} maps to: level 1 for 0-1
304	     * points, level 2 for 2-3 points, level 3 for 4-5 points and level 4 for 6 or more points.
305	     */
306	    int levelForPoints(int points) {
307	        if (points >= 6) {
308	            return 4;
309	        }
310	        if (points >= 4) {
311	            return 3;
312	        }
313	        if (points >= 2) {
314	            return 2;
315	        }
316	        return 1;
317	    }
318	
319	    /**
320	     * The owners belonging to {@code owner}'s household, i.e. those sharing its householdId
321	     * (including the owner itself once persisted). Returns an empty list when the owner has no
322	     * household id assigned.
323	     */
324	    List<Owner> householdMembers(Owner owner) {
325	        String householdId = owner.getHouseholdId();
326	        if (householdId == null) {
327	            return List.of();
328	        }
329	        return clinicService.findAllOwners().stream()
330	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
331	            .toList();
332	    }
333	
334	    /**
335	     * The number of owners belonging to {@code owner}'s household, i.e. those sharing its
336	     * householdId (including the owner itself once persisted). Returns 0 when the owner has no
337	     * household id assigned.
338	     */
339	    int householdSize(Owner owner) {
340	        return householdMembers(owner).size();
341	    }
342	
343	    /**
344	     * The owner's salutation: the {@code title} and last name separated by a single space
345	     * (e.g. 'DR who'), or just the last name when no title has been supplied.
346	     */
347	    String salutation(Owner owner) {
348	        String title = owner.getTitle();
349	        if (title == null || title.isBlank()) {
350	            return owner.getLastName();
351	        }
352	        return title + " " + owner.getLastName();
353	    }
354	
355	    /**
356	     * The upper-cased first letters of firstName and lastName, dot-separated with a
357	     * trailing dot, e.g. 'J.S.'.
358	     */
359	    String initials(Owner owner) {
360	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
361	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
362	    }
363	
364	    public abstract Owner toOwner(OwnerDto ownerDto);
365	
366	    @Mapping(target = "id", ignore = true)
367	    @Mapping(target = "pets", ignore = true)
368	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
369	
370	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
371	
372	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
373	
374	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
375	        OwnerPageDto ownerPageDto = new OwnerPageDto();
376	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
377	        ownerPageDto.setPage(ownerPage.getNumber());
378	        ownerPageDto.setSize(ownerPage.getSize());
379	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
380	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
381	        return ownerPageDto;
382	    }
383	}
