17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.util.Map;
20	
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Resolves an owner's city to its canonical region using a single fixed table.
25	 *
26	 * <p>Keeping this in one place means every rule that is keyed by an owner's region reads
27	 * the same city-to-region mapping, so they can never drift apart: the region a city
28	 * derives here is the region every region-keyed rule sees for that city.
29	 *
30	 * <p>A city not listed in the table has no known region and resolves to
31	 * {@link #UNKNOWN_REGION}.
32	 */
33	@Component
34	public class CityRegionResolver {
35	
36	    /** The region returned for a city that is not in the fixed {@link #CITY_REGION} table. */
37	    public static final String UNKNOWN_REGION = "UNKNOWN";
38	
39	    /** Fixed city-to-region table; a city not listed here has no known region. */
40	    private static final Map<String, String> CITY_REGION = Map.of(
41	        "Sydney", "NSW",
42	        "Melbourne", "VIC",
43	        "Brisbane", "QLD");
44	
45	    /** Fixed region-to-postcode range table (inclusive 4-digit low/high), keyed by region; a
46	     *  region not listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode. */
47	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
48	        "NSW", new int[] {2000, 2099},
49	        "VIC", new int[] {3000, 3099},
50	        "QLD", new int[] {4000, 4099});
51	
52	    /** Fixed region-to-timezone table (IANA names), keyed by region; a region not listed here
53	     *  has no known timezone. */
54	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
55	        "NSW", "Australia/Sydney",
56	        "VIC", "Australia/Melbourne",
57	        "QLD", "Australia/Brisbane");
58	
59	    /**
60	     * Resolve a city to its canonical region.
61	     *
62	     * @param city the owner's city, as stored
63	     * @return the region the city belongs to, or {@link #UNKNOWN_REGION} when the city is
64	     *         not in the fixed table
65	     */
66	    public String regionFor(String city) {
67	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
68	    }
69	
70	    /**
71	     * Resolve a region preferring the postcode over the city. The {@code postcode} is looked up
72	     * against the region postcode ranges first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only
73	     * when the postcode is absent, non-numeric or in no known range does this fall back to the
74	     * city-to-region table. For a known city with a matching postcode both agree; a postcode in a
75	     * different region's range disambiguates cities that share a name.
76	     *
77	     * @param city     the owner's city, as stored
78	     * @param postcode a 4-digit postcode string (e.g. '3000'), or {@code null} when absent
79	     * @return the region derived from the postcode, else the region derived from the city, else
80	     *         {@link #UNKNOWN_REGION}
81	     */
82	    public String regionFor(String city, String postcode) {
83	        String region = regionForPostcode(postcode);
84	        return region != null ? region : regionFor(city);
85	    }
86	
87	    /**
88	     * The region code stamped INSIDE an owner's derived identifiers (the REGION segment of its
89	     * memberId, and the region any other identity code mixes in), resolved preferring the postcode
90	     * over the city exactly as {@link #regionFor(String, String)}.
91	     *
92	     * <p>This is a deliberately separate seam from the user-facing locality region: today both
93	     * resolve to the same canonical region, but keeping the identifier's region derivation in its
94	     * own place means the value woven into identifiers can evolve without disturbing the plain
95	     * region reported as an owner's locality, timezone or segment area.
96	     *
97	     * @param city     the owner's city, as stored
98	     * @param postcode a 4-digit postcode string (e.g. '2000'), or {@code null} when absent
99	     * @return the region code to embed in the owner's identifiers
100	     */
101	    public String identityRegionFor(String city, String postcode) {
102	        return regionFor(city, postcode);
103	    }
104	
105	    /**
106	     * The IANA timezone name for a region, using the fixed region-to-timezone table
107	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane).
108	     *
109	     * @param region the canonical region code (e.g. 'NSW'), such as returned by {@link #regionFor}
110	     * @return the region's IANA timezone name, or {@code null} when the region is not in the table
111	     */
112	    public String timezoneForRegion(String region) {
113	        return REGION_TIMEZONE.get(region);
114	    }
115	
116	    /**
117	     * The region whose postcode range contains {@code postcode}, or {@code null} when the postcode
118	     * is absent, non-numeric or in no known range.
119	     */
120	    private String regionForPostcode(String postcode) {
121	        if (postcode == null || postcode.isBlank()) {
122	            return null;
123	        }
124	        int value;
125	        try {
126	            value = Integer.parseInt(postcode.trim());
127	        }
128	        catch (NumberFormatException ex) {
129	            return null;
130	        }
131	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
132	            int[] range = entry.getValue();
133	            if (value >= range[0] && value <= range[1]) {
134	                return entry.getKey();
135	            }
136	        }
137	        return null;
138	    }
139	
140	    /**
141	     * Whether a 4-digit {@code postcode} is valid for the given {@code city}. The postcode is
142	     * checked against the inclusive range of the city's region (NSW 2000-2099, VIC 3000-3099,
143	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode.
144	     *
